H.background();
const r = P.r;
const mArm = 4;
const Icore = 3;
const L = 12;
const I = Icore + 2 * mArm * r * r;
const omega = L / I;
const cx = 300, cy = 300;
const theta = (omega * t) % (Math.PI * 2);
H.circle(cx, cy, 26, { fill: H.colors.panel, stroke: H.colors.sub, width: 2 });
H.circle(cx, cy - 36, 16, { fill: H.colors.panel, stroke: H.colors.sub, width: 2 });
const rPix = 26 + r * 70;
const ax1 = cx + rPix * Math.cos(theta), ay1 = cy + rPix * Math.sin(theta);
const ax2 = cx - rPix * Math.cos(theta), ay2 = cy - rPix * Math.sin(theta);
H.line(cx, cy, ax1, ay1, { color: H.colors.sub, width: 4 });
H.line(cx, cy, ax2, ay2, { color: H.colors.sub, width: 4 });
H.circle(ax1, ay1, 10, { fill: H.colors.accent });
H.circle(ax2, ay2, 10, { fill: H.colors.accent });
const gx = 640, gy = 300, gR = 80;
H.circle(gx, gy, gR, { stroke: H.colors.grid, width: 2 });
const gpx = gx + gR * Math.cos(theta), gpy = gy + gR * Math.sin(theta);
H.line(gx, gy, gpx, gpy, { color: H.colors.good, width: 3 });
H.text("spin rate", gx - 28, gy + gR + 20, { color: H.colors.sub, size: 12 });
H.text("Angular momentum: L = I omega = constant", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("No external torque: pull arms in (small r) -> I drops -> omega rises", 24, 50, { color: H.colors.sub, size: 13 });
H.text("r = " + r.toFixed(2) + " m   I = " + I.toFixed(2) + " kg*m^2   L = " + L.toFixed(0) + " kg*m^2/s", 24, 72, { color: H.colors.yellow, size: 13 });
H.text("omega = L/I = " + omega.toFixed(2) + " rad/s", 24, 92, { color: H.colors.good, size: 13 });
